package mx.com.mesaregia.inventario.api.controller;
import mx.com.mesaregia.inventario.application.service.AlertaInventarioQueryService; import mx.com.mesaregia.inventario.api.response.AlertaInventarioResponse; import mx.com.mesaregia.inventario.domain.enums.TipoAlertaInventario; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/v1/inventario/alertas") public class AlertaController {private final AlertaInventarioQueryService s;public AlertaController(AlertaInventarioQueryService s){this.s=s;}@GetMapping @PreAuthorize("hasAuthority('inventario.alertas.consultar')")public List<AlertaInventarioResponse> get(@RequestParam Long idAlmacen,@RequestParam(required=false) TipoAlertaInventario tipo){return s.consultar(idAlmacen,tipo);} }
